DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PAM 072", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "46582bce-015e-5089-bf97-2000094b1fb5", "stem": "A linear model for pets versus family size passes through (0,1.2) and (2,2.2). Let a and b be its predictions for families of 8 and 6 members. What is a+b, rounded to the nearest whole number?", "choices": [{"key": "A", "text": "5"}, {"key": "B", "text": "4"}, {"key": "C", "text": "9"}, {"key": "D", "text": "13"}], "type": "mcq", "correct": "C", "explanation": "The slope is (2.2−1.2)/2=0.5, so y=0.5x+1.2. The predictions are a=5.2 and b=4.2. Their sum 9.4 rounds to 9.", "topic": "Statistics, Probability & Data Analysis", "note": "Recovered both labeled graph points. Clarified that noninteger pet counts are model predictions, not exact observed family counts.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 351, "extra_sources": []}, {"id": "clean:HOA 190", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "ecac4362-43a4-5b73-9413-9ba04113911e", "stem": "Which line passes through (0,1.2) and (2,2.2)?", "choices": [{"key": "A", "text": "y=2x+1.2"}, {"key": "B", "text": "y=0.2x+1.2"}, {"key": "C", "text": "y=0.5x+1.2"}, {"key": "D", "text": "y=5x+1.2"}], "type": "mcq", "correct": "C", "explanation": "The y-intercept is 1.2 and slope is (2.2−1.2)/(2−0)=0.5. Thus y=0.5x+1.2.", "topic": "Functions, Transformations & Graphs", "note": "Recovered the shared graph on pages 110 and 351 and transcribed its exact labeled points.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 110, "extra_sources": []}, {"id": "clean:PAM 073", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "c0b55ceb-00a1-58a4-9344-10f01e1e3d69", "stem": "A rectangular prism has volume 945 cubic units, length 4.75 units, and width 3.6 units. What is its height, rounded to one decimal place?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "55.3"}, {"key": "C", "text": "35.6"}, {"key": "D", "text": "71.9"}], "type": "mcq", "correct": "B", "explanation": "Using V=lwh, height=945/(4.75·3.6)=945/17.1≈55.2632, which rounds to 55.3.", "topic": "Coordinate Geometry & Circles", "note": "Verified both copies on pages 352 and 360 and split all four complete questions; made the required rounding explicit.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 352, "extra_sources": [], "parts": [{"label": "Q19", "question_id": "8a1ee0b3-94eb-5419-92cd-847b2d2034df", "stem": "If \\(4^{3x}/2^{y-1}=32\\), what is \\(-30x+5y\\)?", "choices": [{"key": "A", "text": "5"}, {"key": "B", "text": "−5"}, {"key": "C", "text": "20"}, {"key": "D", "text": "−20"}], "type": "mcq", "correct": "D", "explanation": "Rewrite as 2^(6x−y+1)=2⁵, so 6x−y=4. Multiplying by −5 gives −30x+5y=−20.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}, {"label": "Q20", "question_id": "1e991b0e-4839-5fb3-89ea-af95f2445228", "stem": "A line with slope 3 passes through (−2,−7), (−1,a), and (b,2). What is a+b?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "−4"}, {"key": "C", "text": "−3"}, {"key": "D", "text": "−6"}], "type": "mcq", "correct": "C", "explanation": "The first point gives y=3x−1. At x=−1, a=−4. For y=2, 2=3b−1, so b=1. Thus a+b=−3.", "topic": "Functions, Transformations & Graphs", "note": "Confirmed that the first x-value is −2, not +2 as OCR suggested; this restores the correct listed answer."}, {"label": "Q21", "question_id": "f053c9e6-8405-5d26-997c-5f724d210ccb", "stem": "A function is multiplied by 4 whenever x increases by 1, and f(0)=1. Which rule could describe f?", "choices": [{"key": "A", "text": "f(x)=4ˣ"}, {"key": "B", "text": "f(x)=x/4"}, {"key": "C", "text": "f(x)=4x"}, {"key": "D", "text": "f(x)=1.04ˣ"}], "type": "mcq", "correct": "A", "explanation": "For f(x)=4ˣ, f(0)=1 and f(x+1)=4·4ˣ=4f(x). The other choices fail the initial value or the factor-of-four condition.", "topic": "Functions, Transformations & Graphs", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:PAM 076", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "77c59e95-4218-52c7-bfe0-c05b0b0eaf8e", "stem": "How does the graphed function g change as x goes from −2 to 2?", "choices": [{"key": "A", "text": "It decreases by 6."}, {"key": "B", "text": "It decreases by 12."}, {"key": "C", "text": "It decreases by 4."}, {"key": "D", "text": "It increases by 12."}], "type": "mcq", "correct": "B", "explanation": "The graph shows g(−2)=6 and g(2)=−6. The change is −6−6=−12, so g decreases by 12.", "topic": "Functions, Transformations & Graphs", "note": "Recovered the original graph and both endpoint readings; separated the following rational identity.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 354, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "parts": [{"label": "Q9", "question_id": "336d2791-9522-5a30-9f7b-5ca5b04858f0", "stem": "For \\(a+b\\ne0\\), \\((ca^2-cb^2)/(a+b)\\) equals ca plus which expression?", "choices": [{"key": "A", "text": "cb"}, {"key": "B", "text": "−cb"}, {"key": "C", "text": "−b"}, {"key": "D", "text": "1+cb"}], "type": "mcq", "correct": "B", "explanation": "Factor the numerator as c(a−b)(a+b). Cancel a+b to obtain c(a−b)=ca−cb, so the added expression is −cb.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:PAM 079", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Same factor-of-four function question as PAM 073 Q21; correct rule f(x)=4ˣ. Reused that separately published question and excluded the preceding transformation fragment.", "correct": "A", "question_id": "f053c9e6-8405-5d26-997c-5f724d210ccb", "duplicate_of": "clean:PAM 073"}, {"id": "clean:PAM 080", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "fb404c24-c7b4-57c4-babe-88db7fd74c15", "stem": "A parabola has axis of symmetry x=−3.5 and contains (−3.2,−5). What is the other x-coordinate with y=−5?", "choices": [{"key": "A", "text": "−10.2"}, {"key": "B", "text": "−3.8"}, {"key": "C", "text": "6.8"}, {"key": "D", "text": "−3.5"}], "type": "mcq", "correct": "B", "explanation": "The two x-coordinates have midpoint −3.5. Thus (−3.2+x)/2=−3.5, giving x=−3.8.", "topic": "Coordinate Geometry & Circles", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 357, "extra_sources": [], "parts": [{"label": "Q13", "question_id": "e0a38b20-2b0a-52f4-8692-f75a04dab401", "stem": "Using medians of the lower and upper halves, what is the interquartile range of the six numbers 3,20,27,44,60,61?", "choices": [{"key": "A", "text": "59"}, {"key": "B", "text": "20"}, {"key": "C", "text": "60"}, {"key": "D", "text": "40"}], "type": "mcq", "correct": "D", "explanation": "The lower half 3,20,27 has median Q1=20. The upper half 44,60,61 has median Q3=60. The interquartile range is 60−20=40.", "topic": "Statistics, Probability & Data Analysis", "note": "Corrected adaptation: explicitly separated 27 and 44 and stated six values; the source uses an ambiguous dot between them. Specified the quartile convention."}]}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
